[45035] = {id=45035,name="The Call of Battle",level=45,requiredLevel=45,faction="none",expansion=6,zoneID=7543,mapID=646,description="These demons have no honor! Rather than meet us in glorious, open-battle; they hide behind their barricades and siege weapons. The Valarjar have come for the glory of battle and we will not be turned away by cowardly tactics! Destroy their cannons and bring down their barriers, so that our valiant Valarjar may face them in the true spirit of battle! When the dust of battle clears, the corpses of demons shall litter the ground... and the Valarjar will stand triumphant!",questType="world",db2Objectives={{orderIndex=0,type=0,amount=16,objectID=121032,text="Legion Forces slain"},{orderIndex=1,type=0,amount=8,objectID=121013,text="Defenses destroyed"}},worldTaskTitle="The Call of Battle",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
